from datetime import date, datetime

import pytest

from src.clinic.bookings import Booking, Diary, SlotTaken
from src.clinic.slots import slots_for


def test_booking_ends_one_slot_later():
    booking = Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30))
    assert booking.end == datetime(2026, 10, 5, 10, 0)


def test_double_booking_rejected():
    diary = Diary()
    diary.book(Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30)))
    with pytest.raises(SlotTaken):
        diary.book(Booking("Marco Bassi", "Dr Russo", datetime(2026, 10, 5, 9, 30)))


@pytest.mark.parametrize("hour, minute", [(9, 0), (10, 0)])
def test_back_to_back_bookings_allowed(hour, minute):
    diary = Diary()
    diary.book(Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30)))
    diary.book(Booking("Marco Bassi", "Dr Russo", datetime(2026, 10, 5, hour, minute)))
    assert len(diary.bookings) == 2


@pytest.mark.parametrize("hour, minute", [(9, 15), (9, 45)])
def test_partial_overlap_rejected(hour, minute):
    diary = Diary()
    diary.book(Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30)))
    with pytest.raises(SlotTaken):
        diary.book(Booking("Marco Bassi", "Dr Russo", datetime(2026, 10, 5, hour, minute)))
    assert len(diary.bookings) == 1


def test_other_doctor_same_time_allowed():
    diary = Diary()
    diary.book(Booking("Giulia Conti", "Dr Russo", datetime(2026, 10, 5, 9, 30)))
    diary.book(Booking("Marco Bassi", "Dr Neri", datetime(2026, 10, 5, 9, 30)))
    assert len(diary.bookings) == 2


@pytest.mark.parametrize("day", [5, 6, 7, 8])
def test_weekday_slots(day):
    slots = slots_for(date(2026, 10, day))
    assert len(slots) == 19
    assert slots == [
        datetime(2026, 10, day, 8 + (30 + 30 * index) // 60, (30 + 30 * index) % 60)
        for index in range(19)
    ]


def test_friday_slots():
    slots = slots_for(date(2026, 10, 9))
    assert len(slots) == 11
    assert slots[0] == datetime(2026, 10, 9, 8, 30)
    assert slots[-1] == datetime(2026, 10, 9, 13, 30)


@pytest.mark.parametrize("day", [3, 4])
def test_closed_on_weekends(day):
    assert slots_for(date(2026, 10, day)) == []

